import csv, datetime as dt
# Z.1 release dates from federalreserve.gov/releases/z1/release-dates.htm (fetched 2026-10-17); (release_date, latest_quarter)
z1 = """19960912 1996Q2|19961211 1996Q3|19970314 1996Q4|19970612 1997Q1|19970915 1997Q2|19971211 1997Q3|19980313 1997Q4|19980611 1998Q1|19980911 1998Q2|19981211 1998Q3|19990312 1998Q4|19990611 1999Q1|19990915 1999Q2|19991215 1999Q3|20000310 1999Q4|20000609 2000Q1|20000915 2000Q2|20001208 2000Q3|20010309 2000Q4|20010608 2001Q1|20010918 2001Q2|20011207 2001Q3|20020307 2001Q4|20020606 2002Q1|20020916 2002Q2|20021205 2002Q3|20030306 2002Q4|20030605 2003Q1|20030909 2003Q2|20040115 2003Q3|20040304 2003Q4|20040610 2004Q1|20040916 2004Q2|20041209 2004Q3|20050310 2004Q4|20050609 2005Q1|20050921 2005Q2|20051208 2005Q3|20060309 2005Q4|20060608 2006Q1|20060919 2006Q2|20061207 2006Q3|20070308 2006Q4|20070607 2007Q1|20070917 2007Q2|20071206 2007Q3|20080306 2007Q4|20080605 2008Q1|20080918 2008Q2|20081211 2008Q3|20090312 2008Q4|20090611 2009Q1|20090917 2009Q2|20091210 2009Q3|20100311 2009Q4|20100610 2010Q1|20100917 2010Q2|20101209 2010Q3|20110310 2010Q4|20110609 2011Q1|20110916 2011Q2|20111208 2011Q3|20120308 2011Q4|20120607 2012Q1|20120920 2012Q2|20121206 2012Q3|20130307 2012Q4|20130606 2013Q1|20130925 2013Q2|20131209 2013Q3|20140306 2013Q4|20140605 2014Q1|20140918 2014Q2|20141211 2014Q3|20150312 2014Q4|20150611 2015Q1|20150918 2015Q2|20151210 2015Q3|20160310 2015Q4|20160609 2016Q1|20160916 2016Q2|20161208 2016Q3|20170305 2016Q4|20170608 2017Q1|20170921 2017Q2|20171207 2017Q3|20180308 2017Q4|20180607 2018Q1|20180920 2018Q2|20181206 2018Q3|20190307 2018Q4|20190606 2019Q1|20190920 2019Q2|20191212 2019Q3|20200312 2019Q4"""
z1=[(dt.datetime.strptime(a,"%Y%m%d").date(),b) for a,b in (x.split() for x in z1.split("|"))]
fmt=lambda d:"machine-readable zip" if d>=dt.date(1999,6,11) else "PDF only (text)"
with open("z1_release_dates.csv","w",newline="") as f:
    w=csv.writer(f); w.writerow(["release_date","latest_quarter","format","code_households"])
    for d,q in z1: w.writerow([d,q,fmt(d),"154102005" if d<=dt.date(2010,6,10) else "154104005"])
# SPF deadlines (Philadelphia Fed spf-release-dates.txt, fetched 2026-10-17)
spf="""1990Q3 8/23/90|1990Q4 11/22/90|1991Q1 2/16/91|1991Q2 5/18/91|1991Q3 8/18/91|1991Q4 11/16/91|1992Q1 2/22/92|1992Q2 5/15/92|1992Q3 8/21/92|1992Q4 11/20/92|1993Q1 2/19/93|1993Q2 5/20/93|1993Q3 8/19/93|1993Q4 11/23/93|1994Q1 2/21/94|1994Q2 5/18/94|1994Q3 8/18/94|1994Q4 11/18/94|1995Q1 2/21/95|1995Q2 5/22/95|1995Q3 8/22/95|1995Q4 11/20/95|1996Q1 3/2/96|1996Q2 5/18/96|1996Q3 8/21/96|1996Q4 11/18/96|1997Q1 2/19/97|1997Q2 5/17/97|1997Q3 8/16/97|1997Q4 11/19/97|1998Q1 2/18/98|1998Q2 5/16/98|1998Q3 8/15/98|1998Q4 11/14/98|1999Q1 2/16/99|1999Q2 5/15/99|1999Q3 8/14/99|1999Q4 11/13/99|2000Q1 2/12/00|2000Q2 5/13/00|2000Q3 8/12/00|2000Q4 11/11/00|2001Q1 2/14/01|2001Q2 5/12/01|2001Q3 8/15/01|2001Q4 11/14/01|2002Q1 2/12/02|2002Q2 5/13/02|2002Q3 8/14/02|2002Q4 11/13/02|2003Q1 2/14/03|2003Q2 5/12/03|2003Q3 8/16/03|2003Q4 11/14/03|2004Q1 2/14/04|2004Q2 5/14/04|2004Q3 8/13/04|2004Q4 11/13/04|2005Q1 2/9/05|2005Q2 5/12/05|2005Q3 8/11/05|2005Q4 11/8/05|2006Q1 2/8/06|2006Q2 5/10/06|2006Q3 8/9/06|2006Q4 11/8/06|2007Q1 2/8/07|2007Q2 5/9/07|2007Q3 8/8/07|2007Q4 11/7/07|2008Q1 2/7/08|2008Q2 5/8/08|2008Q3 8/7/08|2008Q4 11/10/08|2009Q1 2/10/09|2009Q2 5/12/09|2009Q3 8/11/09|2009Q4 11/10/09|2010Q1 2/9/10|2010Q2 5/11/10|2010Q3 8/10/10|2010Q4 11/9/10|2011Q1 2/8/11|2011Q2 5/10/11|2011Q3 8/8/11|2011Q4 11/8/11|2012Q1 2/7/12|2012Q2 5/8/12|2012Q3 8/7/12|2012Q4 11/6/12|2013Q1 2/11/13|2013Q2 5/7/13|2013Q3 8/12/13|2013Q4 11/18/13|2014Q1 2/10/14|2014Q2 5/11/14|2014Q3 8/11/14|2014Q4 11/10/14|2015Q1 2/10/15|2015Q2 5/12/15|2015Q3 8/11/15|2015Q4 11/10/15|2016Q1 2/9/16|2016Q2 5/10/16|2016Q3 8/9/16|2016Q4 11/8/16|2017Q1 2/7/17|2017Q2 5/9/17|2017Q3 8/8/17|2017Q4 11/7/17|2018Q1 2/6/18|2018Q2 5/8/18|2018Q3 8/7/18|2018Q4 11/6/18|2019Q1 3/12/19|2019Q2 5/7/19|2019Q3 8/6/19|2019Q4 11/11/19"""
qn=lambda q:int(q[:4])*4+int(q[5])-1
rows=[]
for s in spf.split("|"):
    o,d=s.split(); d=dt.datetime.strptime(d,"%m/%d/%y").date()
    prior=[(rd,q) for rd,q in z1 if rd<d]
    if prior: rd,q=prior[-1]; k=qn(o)-qn(q); rows.append([o,d,rd,q,k,fmt(rd)])
    else: rows.append([o,d,"","","","no Z.1 on Fed site before deadline (FRASER only)"])
with open("spf_deadlines_z1_map.csv","w",newline="") as f:
    w=csv.writer(f); w.writerow(["spf_survey","deadline","latest_z1_before_deadline","z1_latest_quarter","k_quarters","z1_format"]); w.writerows(rows)
from collections import Counter
ks=Counter(r[4] for r in rows if r[0]>="1999Q3")
print("k distribution 1999Q3+:",ks); print("z1 releases:",len(z1),"spf surveys:",len(rows))
for r in rows:
    if r[0]>="1999Q3" and r[4]!=2: print("non-2:",r)
